description:
Change under review. Task: rename `fetchProject` to `getProject` everywhere, to match the `getUser` / `getTeam` naming of the other repository functions. Pull request description: "Mechanical rename only. No behaviour change."

The diff is shown in full, in unified format: lines starting with `+` are added, `-` removed, and lines starting with a space are unchanged context.

`src/projects/repository.ts`:
```diff
@@ -12,3 +12,3 @@
-export function fetchProject(db: Db, id: string): ResultAsync<Project, NotFound> {
+export function getProject(db: Db, id: string): ResultAsync<Project, NotFound> {
   return db.projects.findById(id).andThen(requireFound(id));
 }
```

`src/projects/index.ts`:
```diff
@@ -1,1 +1,1 @@
-export { fetchProject, listProjects } from "./repository.js";
+export { getProject, listProjects } from "./repository.js";
```

`src/routes/projects.ts`:
```diff
@@ -3,1 +3,1 @@
-import { fetchProject, listProjects } from "../projects/index.js";
+import { getProject, listProjects } from "../projects/index.js";
@@ -28,5 +28,5 @@ export function showProjectRoute(req: Request, ctx: Ctx): Promise<Response> {
-  return fetchProject(ctx.db, req.params.id).match(
+  return getProject(ctx.db, req.params.id).match(
     (project) => json(project),
     () => notFound(),
   );
 }
@@ -44,8 +44,7 @@ export function deleteProjectRoute(req: Request, ctx: Ctx): Promise<Response> {
-  return fetchProject(ctx.db, req.params.id)
-    .andThen((project) => (project.ownerId === ctx.user.id ? ok(project) : err(forbidden())))
+  return getProject(ctx.db, req.params.id)
     .andThen((project) => ctx.db.projects.delete(project.id))
     .match(
       () => noContent(),
       (failure) => toResponse(failure),
     );
 }
```

